  ui_story_30900301_86_dialog_content = "(Aduh... Ternyata dia lumayan manis.)",
  ui_story_30900301_87_option_content = "Tapi aku tidak cukup baik untuk Barbara...",
  ui_story_30900301_88_dialog_content = "Apakah PlayerName menyukai puisi?",
  ui_story_30900301_89_dialog_content = "\"Bintang-bintang di langit berkelap-kelip di malam hari bukannya di siang hari, beberapa bintang terlihat redup karena mereka berada jauh di sana.\"",
  ui_story_30900301_90_dialog_content = "PlayerName sebenarnya memiliki aura yang indah. Barbara bisa melihatnya karena Barbara selalu ada di sisimu.",
  ui_story_30900301_91_option_content = "Maaf, Barbara, aku mendukung Regina.",
  ui_story_30900301_92_dialog_content = "Aku merasa sedih dan bahagia di waktu bersamaan.",
  ui_story_30900301_93_dialog_content = "Perasaan gugup yang samar ini bisa membantu Barbara tampil lebih baik di atas panggung!",
  ui_story_30900301_94_dialog_content = "Dan... lebih menikmati musiknya!",
  ui_story_30900301_95_dialog_content = "*Berjalan mendekat*",
  ui_story_30900301_96_dialog_content = "*Menatap dengan tenang*",
  ui_story_30900301_97_dialog_content = "*Tiba-tiba tersenyum dengan ceria*",
  ui_story_30900301_98_dialog_content = "Aku ingat, kok!",
  ui_story_30900301_99_option_content = "Hatiku bagaikan batu.",
  ui_story_30900301_100_dialog_content = "Hatiku tidak mudah goyah!",
  ui_story_30900301_101_dialog_content = "Tapi bekas yang tertinggal di hati bak batu ini cenderung menetap lebih lama.",
  ui_story_30900301_102_option_content = "Aku tergila-gila.",
  ui_story_30900301_103_dialog_content = "Meskipun perasaan sekarang ini fana...",
  ui_story_30900301_104_dialog_content = "Perasaan ini layak untuk dihargai selamanya!",
  ui_story_30900301_105_dialog_content = "*Berpura-pura mengambil foto* Senyum!",
  ui_story_30900301_106_dialog_content = "PlayerName selalu bersama Barbara!",
  ui_story_30900301_107_dialog_content = "Aku tiba-tiba ingin menggunakan sebuah kata untuk menggambarkan situasimu...",
  ui_story_30900301_108_dialog_content = "Seperti idola? Haha.",
  ui_story_30900301_109_dialog_content = "Bagaimana Barbara bisa begitu cepat menanggapi?",
  ui_story_30900301_110_dialog_content = "Sebenarnya, kurasa itu bukan hal yang mudah...",
  ui_story_30900301_111_dialog_content = "Pertimbangkan orang lain dulu saja.",
  ui_story_30900301_112_dialog_content = "Aku suka membawa kebahagiaan bagi orang-orang di sekitarku karena itu membuatku senang.",
  ui_story_30900301_113_dialog_content = "Barbara dahulu menerima bantuan dari semua orang, sekarang giliran Barbara untuk membalasnya.",
  ui_story_30900301_114_dialog_content = "Ahh, sudah waktunya latihan.",
  ui_story_30900301_115_dialog_content = "Demi \"<color=#FFB400>Fiery Support</color>\", Barbara sedang berlatih untuk pertunjukan baru. Barbara akan melampaui Regina!",
  ui_story_30900301_116_dialog_content = "Sayang sekali, acara jabat tangan harus berakhir.",
  ui_story_30900301_117_dialog_content = "Ini bingkisan kecil. Jaga baik-baik, PlayerName!",
  ui_story_30900301_118_dialog_content = "Sampai jumpa di lain waktu!",
  ui_story_30900301_119_dialog_content = "(Sesi itu benar-benar bagaikan mimpi. Semua percakapan verbal itu menggunakan banyak sel otakku...)",
  ui_story_30900301_120_dialog_content = "(Tapi... itu bukanlah tantangan yang menyeramkan. Itu hanya seperti acara jabat tangan biasa.)",
  ui_story_30900301_121_dialog_content = "(Mengapa Brock berkata seperti itu tadi?)",
  ui_story_30900301_122_dialog_content = "Eh, bukankah itu?",
  ui_story_30900301_123_dialog_content = "Yo, ini PlayerName, 'kan? Kamu terlihat bingung.",
  ui_story_30900301_124_dialog_content = "Aku baru saja menghadiri acara jabat tangan eksklusif dengan Barbara.",
  ui_story_30900301_125_dialog_content = "Apa gunanya pergi ke acara seperti itu?",
  ui_story_30900301_126_dialog_content = "Hahahaha, yah, kamu juga pernah menghadirinya, Regina.",
  ui_story_30900301_127_dialog_content = "Yah... Iya, betul, memang pernah!",
  ui_story_30900301_128_dialog_content = "Aku membeli setumpuk tiket jabat tangan dan berdebat dengan roti goreng itu selama tiga jam.",
  ui_story_30900301_129_dialog_content = "Hah?",
  ui_story_30900301_130_dialog_content = "Acara jabat tangan Barbara adalah acara rutin di Rediesel Wrench, mengumpulkan banyak penggemarnya...",
  ui_story_30900301_131_dialog_content = "Setelah membeli tiket jabat tangan, peserta bisa mengambil berbagai tantangan dari kotak untuk menantang Barbara.",
  ui_story_30900301_132_dialog_content = "Kita bisa bertanding memberantas Eclipsite, panco dengan beban 150 kg,",
  ui_story_30900301_133_dialog_content = "puasa enam hari, dan bahkan bersaing untuk melihat siapa yang bisa bertahan paling lama tanpa tidur...",
  ui_story_30900301_134_dialog_content = "Sial, aku kalah!! Aku kalah di lomba lari yang merupakan keahlian terbaikku!",
  ui_story_30900301_X134_dialog_content = "Juara pertama lomba itu adalah Barbara, karavan, lalu aku...",
  ui_story_30900301_135_dialog_content = "Tidak begitu menantang...",
  ui_story_30900301_X135_dialog_content = "Tunggu! Mengapa kamu tidak turun dari Modified Buzzsaw-mu itu dulu jika kamu memang merasa hebat?!",
  ui_story_30900301_136_dialog_content = "Jika kamu menang, kamu bisa mendapatkan kembali semua uang yang telah kamu habiskan selama acara jabat tangan, dan akan ada hadiah kejutan—",
  ui_story_30900301_137_dialog_content = "Tapi belum ada yang berhasil.",
  ui_story_30900301_138_dialog_content = "Toh, Jomu yang merencanakan acara itu. Begundal itu tidak menjalankan bisnis yang tidak menguntungkan.",
  ui_story_30900301_139_dialog_content = "Meskipun Barbara terlihat kecil dan lemah, dia itu petarung yang tangguh.",
  ui_story_30900301_140_dialog_content = "Tunggu, jadi tadi aku hampir melawan Barbara ketika aku saja harus bersusah payah berjuang untuk hidupku sendiri?",
  ui_story_30900301_141_dialog_content = "Itu menyeramkan...",
  ui_story_30900301_142_dialog_content = "Tapi anehnya, aku tidak melihat kotak tantangannya, dan Barbara memberitahuku tentang tantangan itu sendiri...",
  ui_story_30900301_143_dialog_content = "Walaupun itu disebut tantangan, Barbara sangat baik kepadaku dan tidak terlihat seperti ingin bertarung.",
  ui_story_30900301_144_dialog_content = "Mungkin karena Jomu tidak ada di sana. Mungkin Barbara yang merencanakan tantangan itu.",
  ui_story_30900301_145_dialog_content = "Barbara sendiri...",
  ui_story_30900301_146_dialog_content = "*Melihat bingkisan dari Barbara*",
  ui_story_30900301_147_dialog_content = "<color=#e8d9bb>Ada secarik kertas dengan tulisan \"Tiket Jabat Tangan\" di bagian depan, dibubuhi tanda tangan Barbara—</color>",
  ui_story_30900301_148_dialog_content = "<color=#e8d9bb>Di bagian belakang ada tulisan, \"Matahari Terbenam yang Indah, kamu adalah hadiah terbaik.\"</color>",
  ui_story_30900301_149_dialog_content = "\"... alam mimpi yang indah.\"",
  ui_story_30900301_150_dialog_content = "\"Lalu, sebagai rasa terima kasihku, aku akan memberimu perlakuan khusus!\"",
  ui_story_30900301_151_dialog_content = "\"Ini adalah RAHASIA antara PlayerName dan Barbara.\"",
  ui_story_30900301_152_dialog_content = "(Seperti itukah, Barbara? \"<color=#FFB400>Satu-satunya</color>\"—benar-benar alam mimpi terbaik)",
  ui_story_30900601_1_dialog_content = "Dan jadi... tamu kehormatan untuk pertunjukan hari ini—",
  ui_story_30900601_2_dialog_content = "Tidak lain adalah The Last Caelestite! Raja lagu cinta Astra sendiri, dan penggemar nomor satu saya—",
  ui_story_30900601_3_dialog_content = "Berikan tepuk tangan untuk PlayerName!!!",
  ui_story_30900601_4_dialog_content = "Wooooo!!!",
  ui_story_30900601_5_dialog_content = "Sepertinya satu-satunya pilihanku... adalah melakukannya saja!",
  ui_story_30900601_6_dialog_content = "<color=#e8d9bb>Semuanya dimulai beberapa hari yang lalu...</color>",
  ui_story_30900601_7_dialog_content = "Ahhhhhhhh! Woooooow—!",
  ui_story_30900601_8_dialog_content = "Uh, Barbara, semua baik-baik saja?",
  ui_story_30900601_9_dialog_content = "Latihan vokalmu tampak sedikit lebih marah dari biasanya hari ini.",
  ui_story_30900601_10_dialog_content = "Ah, PlayerName! Anda akhirnya di sini!",
  ui_story_30900601_11_dialog_content = "Aku marah, sepenuhnya...",
  ui_story_30900601_12_dialog_content = "Fleur memberitahu saya bahwa hotel ini ingin menarik lebih banyak orang untuk pembukaan kembali yang meriah.",
  ui_story_30900601_13_dialog_content = "Dan dia merekomendasikan agar saya datang dan mengadakan pertunjukan! Dan karena panggungnya sangat bagus, saya hanya harus menerima...",
  ui_story_30900601_14_dialog_content = "Lho, berarti bagus, 'kan?",
  ui_story_30900601_15_dialog_content = "Ya, tapi hanya ada satu masalah kecil...",
  ui_story_30900601_16_dialog_content = "Tidak ada seorang pun di sini!!!",
  ui_story_30900601_17_dialog_content = "Beberapa orang berhenti untuk melihat, tetapi tidak ada yang tinggal cukup lama untuk saya menyelesaikan lagu saya! Saya bahkan tidak bisa sampai ke bagian paduan suara sebagian besar waktu!",
  ui_story_30900601_18_dialog_content = "Kenapa cinta dan energiku tidak sampai pada mereka? Apakah ada yang salah dengan diriku?!",
  ui_story_30900601_19_dialog_content = "Kurasa tidak.",
  ui_story_30900601_20_dialog_content = "Saya bahkan mengganti pakaian menjadi baju renang ini untuk pertunjukan. Mereka semua seharusnya sudah terpesona sekarang!",
  ui_story_30900601_21_dialog_content = "Atau apakah baju renangku benar-benar sejelek itu?!",
  ui_story_30900601_22_dialog_content = "...",
  ui_story_30900601_23_dialog_content = "Kelihatannya cukup baik, dan ini sangat cocok untukmu!",
  ui_story_30900601_24_dialog_content = "Saya bisa katakan sekarang juga bahwa ini bukan tentang kamu!",
  ui_story_30900601_25_dialog_content = "Kamu benar-benar berpikir begitu? Ah, PlayerName, aku tahu kau akan mengerti!",
  ui_story_30900601_26_dialog_content = "Jadi, kira-kira apa, ya...?",
  ui_story_30900601_27_dialog_content = "Saya cukup yakin pembukaan kembali Tir' Hotel yang megah ini sedang mengalami beberapa perubahan saat ini.",
  ui_story_30900601_28_dialog_content = "Ketika pertama kali tiba di sini, ada lebih banyak orang muda dari Umbraton dan Rediesel Desert, tapi sekarang...",
  ui_story_30900601_29_dialog_content = "Tempat ini penuh dengan bangsawan Lumopolis dan orang-orang kaya dari Umbraton. Mungkin mereka mencoba menarik tamu-tamu berkelas tinggi?",
  ui_story_30900601_30_dialog_content = "Jadi, mereka mungkin memiliki kecenderungan terhadap musik bergaya Rediesel.",
  ui_story_30900601_31_dialog_content = "Ah... Orang-orang bodoh yang kaku ini sama sekali tidak mengerti keindahan musik!",
  ui_story_30900601_32_dialog_content = "Tapi itu tidak masalah. Keinginan saya adalah berbagi cinta saya dengan semua orang melalui musik saya!",
  ui_story_30900601_33_dialog_content = "Mereka mungkin melihatku dalam cahaya yang salah sekarang, tapi setelah pertunjukanku selesai...",
  ui_story_30900601_34_dialog_content = "Saya yakin mereka semua akan menjadi penggemar saya!",
  ui_story_30900601_35_dialog_content = "Yah... Aku juga yakin begitu!",
  ui_story_30900601_36_dialog_content = "Jadi, ada saran tentang apa yang harus saya ubah tentang performa saya?",
  ui_story_30900601_37_dialog_content = "Saya butuh sesuatu yang akan membuat orang-orang sombong itu tetap memperhatikan saya!",
  ui_story_30900601_38_dialog_content = "Begitu... jadi itulah sebabnya kamu memanggilku ke sini hari ini?",
  ui_story_30900601_39_dialog_content = "Y-Ya, bukan berarti aku mengaku kalah atau apa... Tapi aku hanya tidak bisa memikirkan ide yang bagus sekarang ini!",
  ui_story_30900601_40_dialog_content = "Tapi saya yakin kamu bisa menciptakan sesuatu yang luar biasa!",
  ui_story_30900601_41_dialog_content = "Hmm... Aku memang tahu sedikit tentang selera mereka.",
  ui_story_30900601_42_dialog_content = "Aha, aku tahu aku benar memanggilmu! Sekarang, ajar aku cara terbaik untuk mencuri hati mereka!",
  ui_story_30900601_43_dialog_content = "Untuk permulaan, harus ada rasa kemewahan.",
  ui_story_30900601_44_dialog_content = "Ambil kata-kata pada poster ini, sebagai contoh—",
  ui_story_30900601_45_dialog_content = "\"Reservasi kamar di Tir' Hotel dan dapatkan tiket gratis ke konser Barbara.\"",
  ui_story_30900601_46_dialog_content = "Setiap kali ada sesuatu yang gratis atau mudah didapatkan, orang kaya biasanya mengabaikannya.",
  ui_story_30900601_47_dialog_content = "Tapi bagaimana jika kita mengubahnya sedikit? \"Reservasilah menginap di Hotel Tir' yang terkenal untuk mendapatkan tempat duduk VIP di konser idola eksklusif Barbara.\"",
  ui_story_30900601_48_dialog_content = "Suaranya benar-benar berbeda sekarang!",
  ui_story_30900601_49_dialog_content = "Kamu memang memiliki mata untuk hal semacam ini!",
  ui_story_30900601_50_dialog_content = "Andai saja kamu adalah agenku... Sekarang, apa lagi?!",
  ui_story_30900601_51_dialog_content = "Selanjutnya adalah rasa misteri.",
  ui_story_30900601_52_dialog_content = "Ketika orang kaya tidak memiliki kegiatan yang lebih baik, mereka menghadiri konser. Mereka telah melihat segala macam hal di sana.",
  ui_story_30900601_53_dialog_content = "Itulah sebabnya kita perlu memasukkan sesuatu yang akan menarik rasa ingin tahu mereka! Seperti penampil tamu rahasia!",
  ui_story_30900601_54_dialog_content = "Ohhh! Seorang tamu penampil rahasia... Itu mudah! Bahkan, saya sudah memiliki seseorang dalam pikiran!",
  ui_story_30900601_55_dialog_content = "Apa lagi, apa lagi?!",
  ui_story_30900601_56_dialog_content = "Terakhir adalah rasa takut akan ketinggalan.",
  ui_story_30900601_57_dialog_content = "Tidak ada yang memberikan banyak pikiran pada konser Anda, itulah sebabnya mereka mengabaikannya...",
  ui_story_30900601_58_dialog_content = "Tapi jika mereka mendengar orang-orang di Tir' Hotel mengatakan hal-hal seperti—",
  ui_story_30900601_59_dialog_content = "\"Tidak mungkin! Jangan bilang kamu belum menonton penampilan Barbara! Hanya orang bodoh yang melewatkannya!\"",
  ui_story_30900601_60_dialog_content = "Orang-orang ini akan bergegas datang untuk melihat pertunjukanmu, karena mereka hanya peduli tentang mengikuti orang-orang kaya lainnya!",
  ui_story_30900601_61_dialog_content = "Itu... tidak bisa dipercaya... Dan namun itu sangat masuk akal!",
  ui_story_30900601_62_dialog_content = "Kami tidak memiliki aturan yang tidak berguna seperti itu di Rediesel Desert. Kamu suka sesuatu atau tidak, sesederhana itu!",
  ui_story_30900601_63_dialog_content = "Bagaimana Anda tahu begitu banyak tentang mereka?",
  ui_story_30900601_64_dialog_content = "Yah... Aku memang harus berurusan dengan orang-orang ini dan sikap sombong mereka cukup sering.",
  ui_story_30900601_65_dialog_content = "Tapi semua ini hanya persiapan. Pada akhirnya, menyentuh hati setiap orang...",
  ui_story_30900601_66_dialog_content = "... adalah sesuatu yang hanya bisa kamu lakukan dengan cinta dan energimu, Barbara!",
  ui_story_30900601_67_dialog_content = "Jadi, cukup atur panggung untuk penampilanmu, dan serahkan sisanya padaku!",
  ui_story_30900601_68_dialog_content = "Saya yakin semangat Anda akan menerangi seluruh Tir' Hotel!",
  ui_story_30900601_69_dialog_content = "Heh, jangan lupa siapa yang kamu ajak bicara: satu-satunya Barbara, idola terhebat dan paling sempurna di seluruh Astra!",
  ui_story_30900601_70_dialog_content = "Aku akan membuat mereka semua berteriak memanggil namaku sampai suara mereka habis!",
  ui_story_30900601_71_dialog_content = "<color=#e8d9bb>Jadi, aku menghabiskan beberapa hari berikutnya untuk mempromosikan pertunjukan Barbara dan membuat beberapa perubahan pada panggung...</color>",
  ui_story_30900601_72_dialog_content = "<color=#e8d9bb>Tetapi ketika waktu itu akhirnya tiba...</color>",
  ui_story_30900601_73_dialog_content = "T-T-Tunggu! <size=30>Apakah kamu serius, Barbara? Kamu ingin aku bernyanyi?! Tapi aku belum berlatih apa-apa!!!</size>",
  ui_story_30900601_74_dialog_content = "Dan sejujurnya, nyanyianku bukanlah...",
  ui_story_30900601_75_dialog_content = "Yah, mari kita katakan ini sangat biasa. Ini bukan sesuatu yang ingin saya bagikan dengan dunia!",
  ui_story_30900601_76_dialog_content = "Kamu akan baik-baik saja! Kamu adalah tamu rahasia, dan tidak akan terlalu mengejutkan jika kamu sudah siap!",
  ui_story_30900601_77_dialog_content = "Selain itu, ketika Rediesel Wrench dan The Last Caelestite bekerja sama...",
  ui_story_30900601_78_dialog_content = "Tak ada tim lain seperti kita di dunia ini! Kita tak terhentikan!",
  ui_story_30900601_79_dialog_content = "Faktanya, ini bahkan bisa menjadi debutmu sebagai anggota terbaru dari grup musik terbaru saya, Caelestite Sweethearts!",
  ui_story_30900601_80_option_content = "Setidaknya biarkan aku memikirkannya!",
  ui_story_30900601_81_dialog_content = "Ini bukan sesuatu yang bisa saya putuskan di tempat!",
  ui_story_30900601_82_dialog_content = "Dan setelah itu, kita bisa berlatih bersama dan memperkuat ikatan kita lebih jauh lagi...",
  ui_story_30900601_83_option_content = "Siapa tahu apa yang bisa kita capai!",
  ui_story_30900601_84_dialog_content = "Aku cukup yakin aku hanya akan menahanmu!",
  ui_story_30900601_85_dialog_content = "Demi impianmu, saya rasa saya harus mempertimbangkan kembali...",
  ui_story_30900601_86_dialog_content = "Oh, santailah! Saya hanya mengatakan ini untuk pertunjukan!",
  ui_story_30900601_87_dialog_content = "Bahkan aku harus merencanakan hal seperti ini dengan hati-hati, tahu!",
  ui_story_30900601_88_dialog_content = "Pokoknya, mari kita nyanyikan lagu ini dengan sepenuh hati!",
  ui_story_30900601_89_dialog_content = "Semua orang sudah siap!!!",
  ui_story_30900601_90_dialog_content = "Karena Barbara dan PlayerName...",
  ui_story_30900601_91_dialog_content = "... siap untuk menerangi musim panas Anda!!!",
  ui_story_30900601_92_dialog_content = "Wooooo!!!!",
  ui_story_30900601_93_dialog_content = "Itu dia Caelestite! Itu dia! Seorang Caelestite yang hidup dan bernafas!",
  ui_story_30900601_94_dialog_content = "Kesempatan untuk mendengar Caelestite bernyanyi? Ini luar biasa!",
  ui_story_30900601_95_dialog_content = "Apakah Caelestite terakhir di Astra benar-benar akan bernyanyi dengannya?! Aku tidak sabar untuk melihatnya!",
  ui_story_30900601_96_dialog_content = "Apakah... Apakah aku melakukan pekerjaan promosi yang baik untuk konser Barbara? Orang-orang ini sedikit terlalu bersemangat...",
  ui_story_30900601_97_dialog_content = "Tidak... Itu tidak penting sekarang! Aku harus tetap berirama dengan Barbara!",
  ui_story_30900601_98_dialog_content = "Tak ada yang bisa memberitahuku siapa diriku! ♪",
  ui_story_30900601_99_dialog_content = "A-Aku tidak akan pernah mundur... Bahkan jika itu menyakitkan! ♪",
  ui_story_30900601_100_dialog_content = "Aku akan bernyanyi mengikuti irama ciptaanku sendiri! ♪",
  ui_story_30900601_101_dialog_content = "Di ruang... Antara putih dan hitam! ♪",
  ui_story_30900601_102_dialog_content = "Aku tak akan tersesat dalam kesepian ingatanku! ♪",
  ui_story_30900601_103_dialog_content = "Hei!",
  ui_story_30900601_104_dialog_content = "Aku akan tetap kuat, dan berusaha untuk kehebatan! ♪",
  ui_story_30900601_105_dialog_content = "Hei!",
  ui_story_30900601_106_dialog_content = "(M-Mengesankan...)",
  ui_story_30900601_107_dialog_content = "(Beberapa orang ini hanya datang untuk melihat apa yang terjadi, tetapi sekarang...)",
  ui_story_30900601_108_dialog_content = "(Mereka semua bergerak mengikuti irama lagu Barbara!)",
  ui_story_30900601_109_dialog_content = "(Suasana di Tir' Hotel, baik di atas maupun di luar panggung... Rasanya seperti di Rediesel Desert sekarang!)",
  ui_story_30900601_110_dialog_content = "Lagi! Lagi! Lagi!",
  ui_story_30900601_111_dialog_content = "Sepertinya pekerjaanku di sini sudah selesai...",
  ui_story_30900601_112_dialog_content = "Aku akan pergi diam-diam dan...",
  ui_story_30900601_113_dialog_content = "<color=#e8d9bb>Pat—</color>",
  ui_story_30900601_114_dialog_content = "Kamu belum bisa pergi, PlayerName!",
  ui_story_30900601_115_dialog_content = "Hah? Tapi bagianku sebagai tamu spesial sudah selesai...",
  ui_story_30900601_116_dialog_content = "Siapa yang bilang kamu hanya menyanyikan satu lagu saja?",
  ui_story_30900601_117_dialog_content = "Kamu yang akan menjadi pembawa acara sisanya!",
  ui_story_30900601_118_dialog_content = "Lagi pula, kita membangun panggung sempurna ini bersama-sama.",
  ui_story_30900601_119_dialog_content = "Tidak sopan sekali jika kamu meninggalkan aku sendirian di sini, bukan?",
  ui_story_30900601_120_dialog_content = "Hanya perlakukan konser ini seperti petualangan kita lainnya, dan bantu saya meraih kemenangan!",
  ui_story_30900601_121_dialog_content = "Ba-baik!",
  ui_story_30900601_122_dialog_content = "Ayo lakukan ini, Caelestite!",
  ui_story_30900601_123_dialog_content = "Aku yakin semua orang menantikan ini—",
  ui_story_30900601_124_dialog_content = "Kolaborasi dengan idola terimut, terseksi, dan paling sempurna di Astra: Barbara, the Diesel Sweety!",
  ui_story_30900601_125_dialog_content = "Wooooo!!!",
  ui_story_30900601_126_dialog_content = "Lalu tunjukkan padanya semangatmu! Salurkan melalui saya, penggemar nomor satu-nya!!",
  ui_story_30900601_127_dialog_content = "Wooooo!!!",
  ui_story_30900601_128_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_30900601_129_dialog_content = "... Halo? PlayerName? Kamu tidak menjawabku sepanjang hari, dan sekarang kamu mengabaikanku...",
  ui_story_30900601_130_dialog_content = "Oh, m-maaf... Apakah kamu sedang berbicara padaku?",
  ui_story_30900601_131_dialog_content = "Saya membantu menjadi tuan rumah konser Barbara kemarin, dan sebelum saya menyadarinya...",
  ui_story_30900601_132_dialog_content = "Kami bernyanyi dan berdansa sepanjang hari dan malam!",
  ui_story_30900601_133_dialog_content = "Otakku sedikit kabur sekarang... Lirik Barbara terus bergema di kepalaku...",
  ui_story_30900601_134_dialog_content = "Aku... Aku pikir aku akan pergi tidur! Aku akan membiarkanmu menangani segalanya di Colossus. Terima kasih, Vice..."
}
